<script setup>
import {computed,ref,nextTick,watch} from 'vue'

import HelpTip from '../shared/components/HelpTip.vue'
import {toast} from '../shared/composables/toast.js'
import DubboRequestEditor from './DubboRequestEditor.vue'
import CurlImport from './CurlImport.vue'
import RequestBody from './RequestBody.vue'
import RequestKeyValues from './RequestKeyValues.vue'
import {assertionOptions,extractionSources,setExtractionSource,initializeHeaders,switchHeaderMode,formatJSON,pathParameterKeys,requestDraft,eventSelectionOptions} from './requestEditorModel.js'
const props=defineProps({editor:{type:Object,required:true},disabled:Boolean,available:{type:Array,default:()=>[]},authMode:String})
const dubboEditor=ref(null),tab=ref('parameters'),pathInput=ref(null),headersInput=ref(null),bodyInput=ref(null),firstParameter=ref(null),assertionInputs=[],extractionInputs=[]
watch(()=>props.editor,editor=>initializeHeaders(editor),{immediate:true})
function changeProtocol(value){
 if(value===props.editor.request.mode)return
 const editor=props.editor;editor.protocolDrafts||={};editor.protocolDrafts[editor.request.mode]=JSON.parse(JSON.stringify({request:editor.request,pathValues:editor.pathValues,queryRows:editor.queryRows,headerMode:editor.headerMode,headersJSON:editor.headersJSON,headerRows:editor.headerRows,bodyDrafts:editor.bodyDrafts}))
 const saved=editor.protocolDrafts[value];editor.request=saved?.request||{method:value==='dubbo'?'DUBBO':'GET',path:'/',body:value==='dubbo'?'[]':'',headers:{},mode:value,timeout_seconds:30,assertions:value==='dubbo'?[{type:'rpc_success',path:'',expected:'true'}]:[{type:'status',path:'',expected:'200'}],...(value==='dubbo'?{body_type:'json',rpc:{interface:'',method:'',group:'',version:'',parameter_types:[]}}:{})}
 Object.assign(editor,requestDraft(editor.request),saved||{});if(editor.kind)editor.kind=value==='dubbo'?'dubbo':'http'
}
const pathKeys=computed(()=>pathParameterKeys(props.editor.request.path))
const reference=name=>'{{step.'+name+'}}'
async function focus(field,index=0){if(props.editor.request.mode==='dubbo'){await nextTick();dubboEditor.value?.focus(field,index);return}tab.value=['parameters','headers','body','checks','extractions','settings'].includes(field)?field:'parameters';await nextTick();const control=field==='checks'?assertionInputs[index]:field==='extractions'?extractionInputs[index]:({headers:headersInput,body:bodyInput,parameters:firstParameter}[field]||pathInput).value;focusControl(control);control?.$el?.scrollIntoView({block:'nearest'})}
defineExpose({focus,async addAssertion(assertion){props.editor.request.assertions.push(assertion);await focus('checks',props.editor.request.assertions.length-1)}})
function headerMode(mode){try{switchHeaderMode(props.editor,mode)}catch(e){toast(e.message,'warning');focus('headers')}}
function format(){try{props.editor.request.body=formatJSON(props.editor.request.body);toast('JSON 已格式化','success')}catch{toast('正文不是有效 JSON，已保留原内容','warning');focus('body')}}
function imported(request){const existing=props.editor.extractions;Object.assign(props.editor,requestDraft(request));delete props.editor.bodyDrafts;if(existing)props.editor.extractions=existing;tab.value='parameters';toast('请求已导入草稿，请核对环境目标与路径后发送','success')}
function addExtraction(){props.editor.extractions.push({name:'',source:props.editor.request.mode==='sse'?'sse':'json',path:'/data/id'});focus('extractions',props.editor.extractions.length-1)}

import OptionPicker from '../shared/components/OptionPicker.vue'

import {copyText} from '../shared/clipboard.js'

import {focusControl} from '../shared/focusControl.js'


import {Badge,Button,Empty,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,NumberField,NumberFieldContent,NumberFieldDecrement,NumberFieldIncrement,NumberFieldInput,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsContent,TabsList,TabsTrigger,Textarea} from '../shared/shadcn-ui.js'
</script>
<template><div class="mb-4 flex items-center justify-between gap-3"><OptionPicker :model-value="editor.request.mode||'http'" @update:model-value="changeProtocol" :disabled="disabled" aria-label="调用协议" class="w-44" :options="[{value:'http',label:'HTTP'},{value:'sse',label:'HTTP · SSE'},{value:'dubbo',label:'Dubbo'}]"/><slot v-if="editor.request.mode==='dubbo'" name="actions"/></div><template v-if="editor.request.mode==='dubbo'"><div class="mb-4 flex flex-wrap items-center gap-2"><slot name="tools"/></div><DubboRequestEditor ref="dubboEditor" :editor="editor" :disabled="disabled"/></template><section v-else class="request-editor"><div class="request-line"><OptionPicker v-model="editor.request.method" :disabled="disabled" aria-label="请求方法" style="width:110px" class="method" :options="['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS']"/><Input ref="pathInput" v-model="editor.request.path" :disabled="disabled" placeholder="/api/orders/{id}" aria-label="接口路径"/><slot name="actions"/></div><div v-if="available.length" class="variables flex flex-wrap items-center gap-2"><span>前序步骤变量</span><span v-for="name in available" :key="name" class="min-w-0 break-words"><code>{{reference(name)}}</code><Button variant="ghost" size="xs" aria-label="复制内容" @click="copyText(Array.from($event.currentTarget.parentElement.childNodes).filter(node=>node!==$event.currentTarget).map(node=>node.textContent).join(''))">复制</Button></span></div><div class="request-toolbar"><div :size="4" class="flex flex-wrap items-center gap-2"><CurlImport :disabled="disabled" @import="imported"/><slot name="tools"/></div><div :size="4" class="flex flex-wrap items-center gap-2"><Badge v-if="editor.request.mode==='sse'" :variant="(&quot;blue&quot;)==='red'?'destructive':'secondary'">SSE · {{editor.request.max_events}} 条 / {{editor.request.timeout_seconds}} 秒</Badge><Badge v-if="authMode&&authMode!=='none'" :variant="(&quot;blue&quot;)==='red'?'destructive':'secondary'">环境认证</Badge></div></div><Tabs :model-value="tab" @update:model-value="tab=$event;"><div class="flex min-w-0 items-center gap-2"><TabsList class="h-auto! max-w-full flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;parameters&quot;">参数</TabsTrigger><TabsTrigger :value="&quot;headers&quot;">请求头</TabsTrigger><TabsTrigger :value="&quot;body&quot;">请求正文</TabsTrigger><TabsTrigger :value="&quot;checks&quot;">自动断言</TabsTrigger><TabsTrigger v-if="editor.extractions" :value="&quot;extractions&quot;">响应提取</TabsTrigger><TabsTrigger :value="&quot;settings&quot;">请求设置</TabsTrigger></TabsList></div><TabsContent :value="&quot;parameters&quot;" force-mount v-show="!(tab!==&quot;parameters&quot;)" class="min-w-0"><fieldset v-if="pathKeys.length" class="request-path-values" ><Field v-for="(key,i) in pathKeys" :key="key"><FieldLabel>{{key}} <span class="text-destructive">*</span></FieldLabel><Input :ref="el=>{if(i===0)firstParameter=el}" v-model="editor.pathValues[key]" :disabled="disabled" :aria-label="'路径参数 '+key"/></Field></fieldset><RequestKeyValues :rows="editor.queryRows" label="查询参数" :disabled="disabled" empty="路径中已有查询串会保留，也可在此追加参数"/></TabsContent><TabsContent :value="&quot;headers&quot;" force-mount v-show="!(tab!==&quot;headers&quot;)" class="min-w-0"><Tabs :model-value="editor.headerMode" @update:model-value="headerMode($event);"><TabsList class="h-auto! flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;table&quot;" :disabled="disabled">键值表格</TabsTrigger><TabsTrigger :value="&quot;json&quot;" :disabled="disabled">JSON</TabsTrigger></TabsList></Tabs><div class="header-table"><RequestKeyValues v-if="editor.headerMode==='table'" ref="headersInput" :rows="editor.headerRows" label="请求头" :disabled="disabled" empty="认证由当前环境统一提供"/><Textarea v-else ref="headersInput" v-model="editor.headersJSON" :disabled="disabled" aria-label="请求头 JSON" :rows="({minRows:4,maxRows:12}).minRows||4"/></div></TabsContent><TabsContent :value="&quot;body&quot;" force-mount v-show="!(tab!==&quot;body&quot;)" class="min-w-0"><RequestBody ref="bodyInput" :editor="editor" :disabled="disabled"/></TabsContent><TabsContent :value="&quot;checks&quot;" force-mount v-show="!(tab!==&quot;checks&quot;)" class="min-w-0"><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:900}).y?({x:900}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:900}).x||({x:900}).minWidth||610)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(230)+'px'}">检查类型</TableHead><TableHead>字段 / 响应头</TableHead><TableHead>期望值</TableHead><TableHead :style="{width:(80)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (editor.request.assertions||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker v-model="record.type" :disabled="disabled" aria-label="断言类型" @change="type=>{if(!['sse_json','sse_contains'].includes(type)){delete record.event;delete record.select}}" class="min-w-36" :options="assertionOptions"/><div v-if="['sse_json','sse_contains'].includes(record.type)" class="event-selector"><Input v-model="record.event" :disabled="disabled" placeholder="全部事件类型" aria-label="断言事件类型"/><OptionPicker v-model="record.select" :disabled="disabled" placeholder="最后一条匹配" aria-label="断言事件选择" class="min-w-36" :options="eventSelectionOptions(record.select)"/></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Input v-model="record.path" :disabled="disabled||!['json','header','json_regex','json_range','schema','sse_json'].includes(record.type)" placeholder="/data/id" aria-label="断言字段"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record,rowIndex} in [{record,rowIndex}]"><Textarea v-if="record.type==='schema'" v-model="record.expected" :disabled="disabled" placeholder='{"type":"object","required":["id"]}' aria-label="JSON Schema" :rows="({minRows:2,maxRows:8}).minRows||4"/><Input v-else :ref="el=>assertionInputs[rowIndex]=el" v-model="record.expected" :disabled="disabled" :placeholder="record.type==='json_range'?'[0,100]':record.type==='duration'?'1000':'期望值'" aria-label="断言期望值"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]"><Button @click="editor.request.assertions.splice(rowIndex,1)" variant="ghost" size="default" type="button" :disabled="(disabled)">移除</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(editor.request.assertions||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><Button @click="editor.request.assertions.push({type:'json',path:'',expected:''})" class="add-action" variant="outline" size="default" type="button" :disabled="(disabled||editor.request.assertions.length>=30)">添加断言</Button></TabsContent><TabsContent v-if="editor.extractions" :value="&quot;extractions&quot;" force-mount v-show="!(tab!==&quot;extractions&quot;)" class="min-w-0"><div class="extraction-actions"><Button @click="addExtraction" variant="outline" size="default" type="button" :disabled="(disabled||editor.extractions.length>=10)">添加提取变量</Button><HelpTip text="JSON 使用 /data/id 等 JSON Pointer；SSE 可按事件类型选择第一条或最后一条匹配事件。请求与断言通过后才传给后续步骤。仅支持非空标量，值仅在本次执行内使用。"/></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:850}).y?({x:850}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:850}).x||({x:850}).minWidth||720)+'px'}"><TableHeader><TableRow><TableHead>变量名</TableHead><TableHead :style="{width:(190)+'px'}">来源</TableHead><TableHead>字段 / 响应头</TableHead><TableHead>后续引用</TableHead><TableHead :style="{width:(80)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (editor.extractions||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record,rowIndex} in [{record,rowIndex}]"><Input :ref="el=>extractionInputs[rowIndex]=el" v-model="record.name" :disabled="disabled" placeholder="order_id" aria-label="提取变量名" :maxlength="64"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker :model-value="record.format||record.source" @update:model-value="setExtractionSource(record,$event)" :disabled="disabled" aria-label="提取来源" class="min-w-36" :options="extractionSources"/><div v-if="record.source==='sse'" class="event-selector"><Input v-model="record.event" :disabled="disabled" placeholder="全部事件类型" aria-label="提取事件类型"/><OptionPicker v-model="record.select" :disabled="disabled" placeholder="最后一条匹配" aria-label="提取事件选择" class="min-w-36" :options="eventSelectionOptions(record.select)"/></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Input v-model="record.path" :disabled="disabled" :placeholder="record.source==='header'?'X-Order-ID':'/data/id'" aria-label="提取字段"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><span v-if="record.name" class="min-w-0 break-words"><code>{{reference(record.name)}}</code><Button variant="ghost" size="xs" aria-label="复制内容" @click="copyText(Array.from($event.currentTarget.parentElement.childNodes).filter(node=>node!==$event.currentTarget).map(node=>node.textContent).join(''))">复制</Button></span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]"><Button @click="editor.extractions.splice(rowIndex,1)" variant="ghost" size="default" type="button" :disabled="(disabled)">移除</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(editor.extractions||[]).length"><TableCell :colspan="5"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></TabsContent><TabsContent :value="&quot;settings&quot;" force-mount v-show="!(tab!==&quot;settings&quot;)" class="min-w-0"><div class="request-options"><OptionPicker v-model="editor.request.mode" :disabled="disabled" aria-label="测试类型" style="width:170px" :options="[{value:'http',label:'HTTP 请求'},{value:'sse',label:'SSE 事件流'}]"/><span>超时 / 观察时长</span><NumberField v-model="editor.request.timeout_seconds" :disabled="disabled" :min="1" :max="120" aria-label="测试超时秒数" style="width:100px"><NumberFieldContent><NumberFieldDecrement/><NumberFieldInput/><NumberFieldIncrement/></NumberFieldContent></NumberField><span>秒</span><template v-if="editor.request.mode==='sse'"><span>最多事件</span><NumberField v-model="editor.request.max_events" :disabled="disabled" :min="1" :max="100" aria-label="最多接收事件" style="width:100px"><NumberFieldContent><NumberFieldDecrement/><NumberFieldInput/><NumberFieldIncrement/></NumberFieldContent></NumberField></template><Badge v-if="authMode&&authMode!=='none'" :variant="(&quot;blue&quot;)==='red'?'destructive':'secondary'">复用环境认证 · {{authMode==='login'?'前置获取 Token':'Bearer Token'}}</Badge><HelpTip text="环境、机器与认证在执行时复用；配置的认证头优先。可引用 {{var.API_KEY}}、前序步骤 {{step.order_id}}，以及由测试集关联的 {{case.order_id}}，不在这里重复保存连接或密码。"/></div></TabsContent></Tabs></section></template>
<style scoped>.request-toolbar{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.event-selector{display:grid;gap:6px;margin-top:6px}.request-editor{min-width:0}.request-line{display:flex;gap:10px;align-items:center;margin-bottom:12px}.method{width:110px;flex-shrink:0}.request-line>:nth-child(2){flex:1;min-width:140px}.request-options,.body-tools,.extraction-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}.request-options{color:var(--muted-foreground);font-size:.75rem}.variables,.header-table{margin-top:12px;margin-bottom:12px}.add-action{margin-top:12px}@media(max-width:760px){.request-line{flex-wrap:wrap}}</style>

<style scoped>.request-path-values{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr));gap:16px;margin-bottom:16px;min-width:0}</style>
